using System.Text;
using PostQuantum.FileEncryption.Hybrid;
using Xunit;

namespace PostQuantum.FileEncryption.Tests;

/// <summary>
/// Pinned known-answer vector for hybrid <b>multi-recipient</b> decryption (docs/TEST-VECTORS.md,
/// Vector 8) — a KeySource-4 container wrapping one content key to three recipients, decrypted
/// with the <em>middle</em> recipient's key. It pins what the single-recipient Vector 6 cannot:
/// the KeySource-4 body layout (<c>Count ‖ (Mode ‖ BlockLength ‖ block)*</c>) and the block scan
/// that tries, and skips, a non-matching recipient block before reaching ours. Encryption is
/// randomized, so the vector is decrypt-only. The Rust/WASM core pins the identical bytes
/// (<c>samples/pqfe-wasm/tests/vectors.rs</c>), keeping the two implementations byte-compatible on
/// this path. The key pairs were generated solely for this vector and protect nothing.
/// </summary>
public sealed class HybridMultiRecipientKnownAnswerVectorTests
{
    private static readonly byte[] ExpectedPlaintext = Encoding.UTF8.GetBytes(
        "PostQuantum.FileEncryption hybrid known-answer vector v2.");

    // The MIDDLE recipient's PqHybridPrivateKey.Export() bytes: X25519(32) ‖ ML-KEM-dk(2400).
    private const string PrivateKeyVector =
        "";

    // A .pqfe v2 container, KeySource 4 (multiple recipients), wrapping one content key to three
    // recipients — the key above is the second (middle) of the three.
    private const string ContainerVector =
        "";

    [Fact]
    public async Task Pinned_multi_recipient_container_decrypts_from_the_middle_recipient()
    {
        byte[] container = Convert.FromBase64String(ContainerVector);
        using var privateKey = PqHybridPrivateKey.Import(Convert.FromBase64String(PrivateKeyVector));

        byte[] plaintext = await new PqHybridDecryptor().DecryptBytesAsync(container, privateKey);

        Assert.Equal(ExpectedPlaintext, plaintext);
    }

    [Fact]
    public async Task Pinned_multi_recipient_container_rejects_a_different_key()
    {
        byte[] container = Convert.FromBase64String(ContainerVector);
        using var otherKey = PqHybridKeyPair.Generate();

        await Assert.ThrowsAsync<PqDecryptionException>(() =>
            new PqHybridDecryptor().DecryptBytesAsync(container, otherKey.PrivateKey));
    }

    [Fact]
    public async Task Pinned_multi_recipient_container_fails_closed_when_tampered()
    {
        byte[] container = Convert.FromBase64String(ContainerVector);
        using var privateKey = PqHybridPrivateKey.Import(Convert.FromBase64String(PrivateKeyVector));

        container[^1] ^= 0x01;
        await Assert.ThrowsAsync<PqDecryptionException>(() =>
            new PqHybridDecryptor().DecryptBytesAsync(container, privateKey));
    }
}
